# %%
def show_layouts() -> None:
    ep = make_episodes(1)[0]
    k = 2
    print(f"run {ep['id']} has {len(ep['outs'])} calls; the prompt of call {k} under each layout (key: tokens):")
    for layout in LAYOUTS:
        prompt = build_prompt(ep, k, layout)
        print(f"\n  {LAYOUT_NAMES[layout]}: {sum(t for _, t in prompt)} tokens in {len(prompt)} segments")
        print("   " + "  ".join(f"{key.split('|')[0]}:{t}" for key, t in prompt))
    nxt = {layout: build_prompt(ep, k + 1, layout) for layout in LAYOUTS}
    print(f"\nfirst difference between call {k} and call {k + 1}, by position:")
    for layout in LAYOUTS:
        a, b = build_prompt(ep, k, layout), nxt[layout]
        same = 0
        while same < min(len(a), len(b)) and a[same] == b[same]:
            same += 1
        print(f"  {LAYOUT_NAMES[layout]:<22} the first {same} segment{'' if same == 1 else 's'} {'is' if same == 1 else 'are'} identical")


if __name__ == "__main__":
    _try("layouts of one run", show_layouts, needs=("exercise 1",))


# %% [markdown]
# ## 3. Exercise 2: what the cache serves
#
# **`shared_prefix_tokens(a, b)`**: the number of tokens, a whole number (an `int`), in the longest run of **leading** segments that `a` and `b` have in common. Neither list is changed, and an empty list shares nothing. Segments
# are compared whole (`(key, tokens)` equal to `(key, tokens)`), position by position from the start, and the count **stops at the first
# difference**: an equal segment after a mismatch does not count, and a segment that appears in both prompts at different positions does not count. A segment of 0 tokens is still a segment: equal ones in the shared run add nothing and do not end it. Segments built separately are equal when their key and tokens are equal: compare them with `==`, never with `is`, and compare the whole key (`res|7|0` and `res|7|1` are different keys). The shared run can be any number of segments long: the prompt of a late call in a long run has many segments, and nearly all of them can be shared, so do not stop the walk after the first few.
#
# **`cache_hit_tokens(prompt, entries, now, ttl, min_tokens)`**: `entries` is a list of `(stored_at, stored_prompt)` in any order, times in
# whole seconds, none in the future. An entry is **live** while `now - stored_at < ttl`: an entry exactly `ttl` seconds old has expired. `ttl` and `min_tokens` are arguments, not constants: the providers' lifetimes and minimum lengths differ, so use the values you are given. Return, as an `int`, the
# largest `shared_prefix_tokens(prompt, stored_prompt)` over the live entries, or `0` if that largest value is below `min_tokens` (a run of exactly
# `min_tokens` is served). Matches from different entries are never added together. A stored prompt can be longer than the new one (more segments, or more tokens): it serves the leading part the two share, and that shared part, not the stored prompt's own length, is what counts towards `min_tokens`. The list is not sorted by time: an expired entry can sit anywhere, with live entries before and after it, so skip it and carry on. `entries` can hold hundreds of prompts: look at every one. A live entry that shares nothing with the new prompt, or less than `min_tokens`, or less than the best match found so far, does not end the search: keep going to the end of the list, whatever order the entries are in (do not `break` or `return` early on a live entry). The same prompt can be stored more than once, at different times: every copy is judged on its own age (storing a prompt again does not refresh or shorten an earlier copy's lifetime, an expired copy never hides a live one, and a live copy is not hidden by an older expired one), so the match counts if any live copy shares it. A stored prompt that is **identical** to the new one is not a special case: while it is live it serves the whole prompt, but only if that whole prompt reaches `min_tokens`, and once it is `ttl` seconds old it serves nothing. Leave `entries` and `prompt` as you found them.
#
# <details><summary>💡 Hint 1 — what to think about</summary>
#
# Two things can stop a stored prompt from helping: it has expired, or it shares too little. Which of the two decides whether an entry is looked
# at at all, and what do you compare with the minimum?
#
# </details>
# <details><summary>💡 Hint 2 — the approach in words</summary>
#
# Walk the two lists together and stop at the first pair that is not equal, adding up tokens as you go. For the cache, keep the best
# value seen among live entries, then apply the minimum once at the end (applying it to each entry first gives the same answer).
#
# </details>

# %%
def shared_prefix_tokens(a: list, b: list) -> int:
    """Tokens in the longest run of leading segments equal in `a` and `b` (see the rules above).

    Example:
        >>> shared_prefix_tokens([("s", 10), ("t", 5), ("u", 7)], [("s", 10), ("t", 5), ("v", 7)])    # doctest: +SKIP
        15

    Returns:
        an int, 0 when the first segments differ
    """
    # YOUR CODE HERE
    raise NotImplementedError


def cache_hit_tokens(prompt: list, entries: list, now: int, ttl: int, min_tokens: int) -> int:
    """Tokens of `prompt` served from the cache (see the rules above).

    Example (one live entry sharing 15 tokens, minimum 10; the same entry with minimum 16):
        >>> cache_hit_tokens(p, [(100, q)], 150, 300, 10), cache_hit_tokens(p, [(100, q)], 150, 300, 16)    # doctest: +SKIP
        (15, 0)

    Returns:
        an int; entries is not modified
    """
    # YOUR CODE HERE
    raise NotImplementedError


_S, _T, _U, _V = ("seg-s", 10), ("seg-t", 5), ("seg-u", 7), ("seg-v", 7)


def _rebuilt(prompt: list) -> list:
    """The same prompt built again at run time: equal segments, but new tuple and string objects, as `build_prompt` makes on every call."""
    return [("".join(list(key)), int(str(tokens))) for key, tokens in prompt]


def _retokened(prompt: list) -> list:
    """The same prompt with every token count rebuilt as a new int object (equal value; above 256 it is not the same object), the keys left alone."""
    return [(key, int(str(tokens))) for key, tokens in prompt]


def _case_prefix_basics():
    got = shared_prefix_tokens([_S, _T], [_S, _T, _U])
    assert got == 15, f"got {got}: the first prompt is a prefix of the second, so they share its tokens (10 + 5)"
    got = shared_prefix_tokens([_S, _T, _U], [_S, _T])
    assert got == 15, f"got {got}: the second prompt is a prefix of the first, so they share its tokens (10 + 5): the answer does not depend on which argument is longer"
    got = shared_prefix_tokens([], [_S])
    assert got == 0, f"got {got}: an empty first prompt shares nothing"
    got = shared_prefix_tokens([_S], [])
    assert got == 0, f"got {got}: an empty second prompt shares nothing"
    got = shared_prefix_tokens([_S, _T, _U], _rebuilt([_S, _T, _V]))
    assert got == 15, (
        f"got {got}: segments are equal when their key and tokens are equal, even if they are different objects built separately (as every prompt `build_prompt` returns is): "
        "compare them with ==, not with `is`")
    got = shared_prefix_tokens([("seg-big", 1000), _T], _rebuilt([("seg-big", 1000), _T]))
    assert got == 1005, (
        f"got {got}: a count of 1000 tokens built separately is equal to another 1000 but is not the same object; compare the token counts with ==, not with `is`")
    got = shared_prefix_tokens([("empty", 0), _S, _T], [("empty", 0), _S, _T])
    assert got == 15, f"got {got}: an equal segment of 0 tokens adds nothing and does not end the run, so the shared run goes on through it (10 + 5 after it)"
    got = shared_prefix_tokens([_S, _T, _U], [_S, _V])
    assert type(got) is int, f"shared_prefix_tokens returned a {type(got).__name__} ({got!r}): the number of tokens is a whole number, an int"
    left, right = [_S, _T, _U], [_S, _T, _V]
    shared_prefix_tokens(left, right)
    assert left == [_S, _T, _U], "shared_prefix_tokens changed its first list (for example by popping segments off it); walk the lists, do not consume them"
    assert right == [_S, _T, _V], "shared_prefix_tokens changed its second list (for example by popping segments off it); walk the lists, do not consume them"


def _case_prefix_stops_at_first_difference():
    got = shared_prefix_tokens([_S, _T, _U], [_S, _V, _U])
    assert got == 10, f"got {got}: the run stops at the first difference, so the equal third segment after a mismatch does not count (and neither does the mismatching one)"
    got = shared_prefix_tokens([_S, _T], [_T, _S])
    assert got == 0, f"got {got}: the same segments in another order share nothing: matching is by position from the start"
    got = shared_prefix_tokens([("seg-s", 10)], [("seg-s", 12)])
    assert got == 0, f"got {got}: a segment with the same key but a different token count is a different segment"
    got = shared_prefix_tokens([("act|7|0", 3), ("res|7|0", 100)], [("act|7|0", 3), ("res|7|1", 100)])
    assert got == 3, (
        f"got {got}: the first segments agree, the second pair has the same tokens and keys that differ only after the last '|' (res|7|0 against res|7|1): the run stops there, at 3 tokens; "
        "compare the whole key and the token count (a key with another key's tokens is a different segment)")


_LONG_RUN = [(f"seg-{j}", j) for j in range(1, 61)]      # 60 segments of 1 to 60 tokens: 1830 tokens


def _case_hit_long_shared_runs():
    got = shared_prefix_tokens(_LONG_RUN + [("tail-a", 7)], _LONG_RUN + [("tail-b", 7)])
    assert got == 1830, f"got {got}: two prompts share 60 segments (1830 tokens) and then differ; the shared run can be any number of segments long, so walk it to the first difference"
    got = shared_prefix_tokens(_LONG_RUN, _LONG_RUN + [("tail", 7)])
    assert got == 1830, f"got {got}: the first prompt is a 60-segment prefix of the second, so they share all its 1830 tokens; the shared run can be any number of segments long"
    got = cache_hit_tokens(_STATIC_7, [(100, _STATIC_7[:-1] + [("clock|7|6", CLOCK_TOKENS)])], 120, 300, 1)
    assert got == 888, (f"got {got}: the only live entry is a prompt of the same run that shares the first 17 segments (tools, system, task and fourteen turns: 888 tokens) and "
                        "differs in the clock; a long shared run is served in full, however many segments it has")


def _case_hit_best_live_entry():
    p = [_S, _T, _U]
    entries = [(100, [_S]), (100, [_S, _T, _V]), (100, [_S, _T])]
    got = cache_hit_tokens(p, entries, 120, 300, 1)
    assert got == 15, f"got {got}: serve the largest shared prefix over the live entries (15 tokens), not the first entry's 10"
    got = cache_hit_tokens(p, entries[::-1], 120, 300, 1)
    assert got == 15, f"got {got}: serve the largest shared prefix over the live entries (15 tokens), not the last entry's 10, whatever the order of the list"
    got = cache_hit_tokens(p, [], 120, 300, 1)
    assert got == 0, f"got {got}: no entries, nothing is cached"
    got = cache_hit_tokens(p, entries, 120, 300, 1)
    assert type(got) is int, f"cache_hit_tokens returned a {type(got).__name__} ({got!r}): the tokens served are a whole number, an int"
    got = cache_hit_tokens(p, entries, 120, 300, 16)
    assert type(got) is int, f"cache_hit_tokens returned a {type(got).__name__} ({got!r}) when the match was too short: nothing served is the int 0"
    got = cache_hit_tokens(p, [(120, [_S, _T])], 120, 300, 1)
    assert got == 15, f"got {got}: an entry stored in the same second is live (age 0)"
    got = cache_hit_tokens(_rebuilt(p), [(100, _rebuilt([_S, _T, _V]))], 120, 300, 1)
    assert got == 15, (f"got {got}: the stored prompts and the new prompt were built separately, so their segments are equal but not the same objects; "
                       "compare segments with ==, not `is` (the replay below builds every prompt afresh)")
    big = [("seg-big", 1000), _T, _U]
    got = cache_hit_tokens(big, [(100, _retokened([("seg-big", 1000), _T, _V]))], 120, 300, 1)
    assert got == 1005, f"got {got}: the new prompt and the stored one hold equal segments of 1000 and 5 tokens, the counts built separately; compare token counts with ==, not `is`"


def _case_hit_weak_entries_do_not_end_the_search():
    p = [_S, _T, _U]
    got = cache_hit_tokens(p, [(0, [_U]), (0, [_S, _T])], 10, 300, 1)
    assert got == 15, (
        f"got {got}: a live entry that shares nothing, before the best one, must not stop the search: look at every live entry (do not break or return early)")
    got = cache_hit_tokens(p, [(0, [_S]), (0, [_S, _T])], 10, 300, 11)
    assert got == 15, (
        f"got {got}: a live entry that shares 10 tokens, under a minimum of 11, must not stop the search: the entry that shares 15 is still found")
    got = cache_hit_tokens(p, [(0, [_S]), (0, [_U]), (0, [_S, _T])], 10, 300, 1)
    assert got == 15, (
        f"got {got}: a live entry that shares less than the best so far must not stop the search: look at every live entry to the end")


def _case_hit_unrelated_entries_do_not_stop_the_search():
    p = [_S, _T, _U]
    pool = [(0, [_U]), (0, [_V]), (0, [_S]), (0, [_S, _T])]
    for minimum in (1, 11):
        for order in itertools.permutations(pool):
            got = cache_hit_tokens(p, list(order), 10, 300, minimum)
            assert got == 15, (  # lint: one-condition (sweep: every order of four live entries sharing 0, 0, 10 and 15 tokens, at two minimums; the single-input asserts are in _case_hit_weak_entries_do_not_end_the_search)
                f"got {got} from four live entries sharing 0, 0, 10 and 15 tokens, with minimum {minimum}, stored in the order {[q for _, q in order]}: the best is 15; "
                "a live entry that shares nothing, or less than the minimum, or less than the best so far does not end the search, so do not break or return early, keep going to the end")


def _case_hit_lifetime_boundary():
    p = [_S, _T, _U]
    got = cache_hit_tokens(p, [(1000, [_S, _T])], 1299, 300, 1)
    assert got == 15, f"got {got}: an entry 299 s old with a 300 s lifetime is live (live while now - stored_at < ttl)"
    got = cache_hit_tokens(p, [(1000, [_S, _T])], 1300, 300, 1)
    assert got == 0, f"got {got}: an entry exactly 300 s old with a 300 s lifetime has expired (live only while now - stored_at < ttl)"
    got = cache_hit_tokens(p, [(1000, [_S, _T])], 1000, 300, 1)
    assert got == 15, f"got {got}: an entry stored in this very second (age 0) is live"
    got = cache_hit_tokens(p, [(0, [_S, _T, _U]), (200, [_S])], 400, 300, 1)
    assert got == 10, f"got {got}: the long match is 400 s old and has expired, so only the live short match counts (10 tokens): an expired entry never counts, whatever it shares"
    got = cache_hit_tokens(p, [(5000, [_S, _T])], 5100, 60, 1)
    assert got == 0, f"got {got}: with a lifetime of 60 s an entry 100 s old has expired: the lifetime is an argument (the providers' differ), not a constant"
    got = cache_hit_tokens(p, [(5000, [_S, _T])], 6000, 1800, 1)
    assert got == 15, f"got {got}: with a lifetime of 1800 s an entry 1000 s old is live: the lifetime is an argument (the providers' differ), not a constant"


def _case_hit_minimum_boundary():
    p = [_S, _T, _U]
    got = cache_hit_tokens(p, [(0, [_S, _T])], 10, 300, 15)
    assert got == 15, f"got {got}: a run of 15 tokens with a minimum of 15 is served (exactly the minimum is enough)"
    got = cache_hit_tokens(p, [(0, [_S, _T])], 10, 300, 16)
    assert got == 0, f"got {got}: a run of 15 tokens with a minimum of 16 is not served (one token short)"
    got = cache_hit_tokens(p, [(0, [_S]), (0, [_S])], 10, 300, 12)
    assert got == 0, f"got {got}: two entries that each share 10 tokens must not be added together to reach a minimum of 12"
    same = [_S, _T]
    got = cache_hit_tokens(same, [(0, same)], 10, 300, 20)
    assert got == 0, (f"got {got}: the stored prompt is identical to the new one (15 tokens in all) and live; with a minimum of 20 nothing is served: "
                      "an identical live prompt is not served whole whatever its length, the minimum applies to it like to any other shared run")
    got = cache_hit_tokens(same, [(0, same)], 10, 300, 1)
    assert got == 15, f"got {got}: the stored prompt is identical to the new one and live (10 s old, lifetime 300 s), so it serves the whole prompt, 15 tokens: an identical live prompt is not skipped"
    got = cache_hit_tokens(same, [(1000, same)], 1300, 300, 1)
    assert got == 0, f"got {got}: an identical stored prompt exactly 300 s old with a 300 s lifetime has expired: an identical prompt expires like any other"


def _case_hit_many_entries():
    p = [_S, _T, _U]
    crowd = [(1000 + j, [_S, (f"z{j}", 1)]) for j in range(300)]
    best = (1100, [_S, _T, _V])
    got = cache_hit_tokens(p, [best] + crowd, 1400, 1000, 1)
    assert got == 15, f"got {got} from 301 live entries: the best match (15 tokens) is the first in the list, so look at every entry, not only the last few"
    got = cache_hit_tokens(p, crowd + [best], 1400, 1000, 1)
    assert got == 15, f"got {got} from 301 live entries: the best match (15 tokens) is the last in the list, so look at every entry, not only the first few"


def _case_hit_expired_entry_anywhere():
    p = [_S, _T, _U]
    got = cache_hit_tokens(p, [(150, [_S, _T]), (0, [_S, _T, _U])], 400, 300, 1)
    assert got == 15, (f"got {got}: the best live entry (stored at 150) comes before an expired one (stored at 0): the list is not in time order, so skip an expired "
                       "entry and carry on, never stop at it (and do not walk the list backwards)")
    got = cache_hit_tokens(p, [(350, [_S]), (0, [_S, _T, _U]), (150, [_S, _T])], 400, 300, 1)
    assert got == 15, (f"got {got}: a live entry, an expired one, then the best live one: skip the expired entry and carry on, never stop at it, "
                       "even after a live entry has been found")


def _case_hit_any_order():
    p = [_S, _T, _U]
    live_short, live_best = (350, [_S]), (150, [_S, _T])
    gone_long, gone_longer = (0, [_S, _T, _U]), (10, [_S, _T, _U, _V])
    for order in itertools.permutations([live_short, gone_long, live_best, gone_longer]):
        got = cache_hit_tokens(p, list(order), 400, 300, 1)
        assert got == 15, (  # lint: one-condition (sweep: all 24 orders of two live and two expired entries; the single-input asserts are in _case_hit_expired_entry_anywhere)
            f"got {got} from the entries stored at {[t for t, _ in order]} (now 400, lifetime 300): the entries stored at 0 and 10 have expired, "
            "the best live one shares 15 tokens; whatever order the list is in, skip an expired entry and carry on, never stop at it")


def _case_hit_same_prompt_stored_twice():
    p = [_S, _T, _U]
    old_copy, new_copy = (0, [_S, _T]), (500, [_S, _T])
    got = cache_hit_tokens(p, [old_copy, new_copy], 600, 300, 1)
    assert got == 15, (f"got {got}: the same prompt is stored at 0 s (expired, 600 s old) and at 500 s (live, 100 s old); every copy is judged on its own age, "
                       "so the live copy serves 15 tokens even though the expired copy comes first; do not keep only the first or the oldest copy of a prompt")
    got = cache_hit_tokens(p, [new_copy, old_copy], 600, 300, 1)
    assert got == 15, (f"got {got}: the same prompt is stored at 500 s (live) and at 0 s (expired); every copy is judged on its own age, "
                       "so the live copy serves 15 tokens even though the expired copy comes last; do not keep only the last or the oldest copy of a prompt")


def _case_hit_longer_stored_prompt():
    p = [_S, _T]
    got = cache_hit_tokens(p, [(0, [_S, _T, _U])], 10, 300, 1)
    assert got == 15, f"got {got}: the stored prompt has one more segment than the new one, and the two share 15 tokens; a longer stored prompt serves the leading part it shares"
    got = cache_hit_tokens(p, [(0, [_S, _T, _U])], 10, 300, 16)
    assert got == 0, (f"got {got}: the stored prompt holds 22 tokens but shares only 15 with the new one: the minimum applies to the shared part, "
                      "so a minimum of 16 serves nothing")
    got = cache_hit_tokens(p, [(0, [_S, _T, _U])], 400, 300, 1)
    assert got == 0, f"got {got}: a longer stored prompt that has expired serves nothing"


def _case_hit_leaves_entries_alone():
    entries = [(5, [_S, _T]), (900, [_S]), (1, [_U])]
    before = [(t, list(q)) for t, q in entries]
    new_prompt = [_S, _T]
    got = cache_hit_tokens(new_prompt, entries, 950, 300, 1)
    assert new_prompt == [_S, _T], "cache_hit_tokens changed the prompt it was given (it has no business storing, trimming or extending it); leave prompt as you found it"
    assert got == 10, f"got {got}: only the entry stored at 900 is live (the other two are over 300 s old), and it shares 10 tokens"
    assert entries == before, "cache_hit_tokens changed the list it was given (sorted it, dropped expired entries, or edited a prompt); leave entries as you found it"


_CASES_HIT = [_case_prefix_basics, _case_prefix_stops_at_first_difference, _case_hit_long_shared_runs, _case_hit_best_live_entry, _case_hit_weak_entries_do_not_end_the_search,
              _case_hit_unrelated_entries_do_not_stop_the_search, _case_hit_many_entries, _case_hit_lifetime_boundary, _case_hit_minimum_boundary,
              _case_hit_expired_entry_anywhere, _case_hit_any_order, _case_hit_same_prompt_stored_twice, _case_hit_longer_stored_prompt, _case_hit_leaves_entries_alone]


def _check_cache() -> None:
    for case in _CASES_HIT:
        case()
    print("exercise 2 looks right")


