def show_layout_table() -> None:
    eps = make_episodes()
    print(f"{N_EP} agent runs, latency budget {BUDGET_MS} ms; cost in dollars, latency modelled (ms)")
    results, printed = {}, {}
    for name, profile in PROFILES.items():
        print(f"\n{name}  (read {float(profile['read']):.2f}, write {float(profile['write']):.2f}, input {float(profile['input']):.2f} per million)")
        print(f"  {'layout':<22}{'total cost':>12}{'per success':>13}{'succeeded':>11}{'late':>6}{'p95 latency':>13}{'read from cache':>17}")
        rows = [("no caching", replay(eps, "static_first", profile, caching=False))]
        rows += [(LAYOUT_NAMES[layout], replay(eps, layout, profile)) for layout in LAYOUTS]
        results[name] = rows
        printed[name] = []
        for label, r in rows:
            s = r["summary"]
            per = _usd(s["cost_per_success"]) if s["cost_per_success"] is not None else "none"
            line = (f"  {label:<22}{_usd(s['cost_total'], 2):>12}{per:>13}{s['succeeded']:>11}{s['late']:>6}{str(s['p95_ms']) + ' ms':>13}"
                    f"{'≈%.1f%%' % (100 * r['read'] / r['input']):>17}")
            printed[name].append(line)
            print(line)
    print("\nchange in cost per success against no caching, and in total cost:")
    for name, rows in results.items():
        base = rows[0][1]["summary"]
        changes = []
        for label, r in rows[1:]:
            s = r["summary"]
            if s["cost_per_success"] is None or base["cost_per_success"] is None:
                continue
            changes.append((s["cost_per_success"] / base["cost_per_success"] - 1, s["cost_total"] / base["cost_total"] - 1, label, s["succeeded"]))
        biggest = max(changes, key=lambda c: abs(c[0]))
        cells = ", ".join(f"{label} {'≈%+.0f%%' % (100 * per)} ({'≈%+.0f%%' % (100 * tot)} total)" for per, tot, label, _ in changes)
        print(f"  {name}: {cells}")
        print(f"    the layout that moved cost per success the most was {biggest[2]} ({'≈%+.0f%%' % (100 * biggest[0])})")
        print(f"    that change has two parts: total cost {'≈%+.0f%%' % (100 * biggest[1])}, and successes {base['succeeded']} runs without caching, {biggest[3]} runs with it "
              f"({'≈%+.0f%%' % (100 * (Fraction(biggest[3], base['succeeded']) - 1))}): cost per success is the first divided by the second, so cheaper tokens are only part of it")
        shares = {label: Fraction(r["read"], r["input"]) for label, r in rows[1:]}
        for per, tot, label, _ in changes:
            if tot > 0:
                print(f"    {label} cost more in total than not caching at all, with cache reads covering {'≈%.1f%%' % (100 * shares[label])} of its input tokens:"
                      " every input token it did not read was written at the write price")
    names = list(printed)
    for a in range(len(names)):
        for b in range(a + 1, len(names)):
            if printed[names[a]] == printed[names[b]]:
                pa, pb = PROFILES[names[a]], PROFILES[names[b]]
                print(f"\n{names[a]} and {names[b]} print identical rows here (input price {float(pa['input']):.2f} and {float(pb['input']):.2f}, minimums "
                      f"{pa['min_tokens']} and {pb['min_tokens']} tokens, lifetimes {pa['ttl_s']} s and {pb['ttl_s']} s): at this traffic, the table cannot tell them apart; section 7 varies the traffic.")
    print("\nthe layouts hold the same tokens; only the order differs")


